  .MemWrData(u_fifo2_MemWrData),
  .MemRdAddr(u_fifo2_MemRdAddr),
  .MemRdEn(u_fifo2_MemRdEn)
);
defparam u_fifo2.DATA_WIDTH_WR = 64;
defparam u_fifo2.DATA_WIDTH_RD = 64;
