  .ReB(1'b1),
  .DataInA(u_fifo2_MemWrData[63:0]),
  .AddressA(u_fifo2_MemWrAddr[8:0]),
  .AddressB(u_fifo2_MemRdAddr[8:0]),
  .AddressStallB(~u_fifo2_MemRdEn),
  .DataOutB(u_fifo2_mem__DataOutB)
