assign WrEmpty = u_fifo2_WrEmpty;
assign WrFull = u_fifo2_WrFull;
assign WrUsedw = u_fifo2_WrUsedw[8:0];
assign RdEmpty = u_fifo2_RdEmpty;
assign RdFull = u_fifo2_RdFull;
assign RdUsedw = u_fifo2_RdUsedw[8:0];
